def solution(starts, durations):
    import heapq
    active_ends = []
    best = 0
    for start, duration in sorted(zip(starts, durations)):
        while active_ends and active_ends[0] <= start:
            heapq.heappop(active_ends)
        heapq.heappush(active_ends, start + duration)
        best = max(best, len(active_ends))
    return best

def solution(loads, batches, setup):
    def feasible(limit):
        used = 1
        current = 0
        count = 0
        for load in loads:
            addition = load if count == 0 else setup + load
            if current + addition > limit:
                used += 1
                current = load
                count = 1
                if used > batches:
                    return False
            else:
                current += addition
                count += 1
        return True
    low = max(loads)
    high = sum(loads) + setup * (len(loads) - 1)
    while low < high:
        middle = (low + high) // 2
        if feasible(middle):
            high = middle
        else:
            low = middle + 1
    return low
